arguments.command:
python -c "
from semver import parse
try:
    parse('1.2.3')
    print('valid parse OK')
except Exception as e:
    print(f'valid parse: {e}')

try:
    parse('invalid')
    print('invalid parse OK')
except ValueError as e:
    print(f'invalid parse ValueError: {e}')
except Exception as e:
    print(f'invalid parse: {type(e).__name__}: {e}')
"
